export interface Product {
  id: number;
  name: string;
  price: number;
}

export async function getAllProducts(): Promise<Product[]> {
  await new Promise(resolve => setTimeout(resolve, 100));

  return [
    { id: 1, name: 'Laptop', price: 999 },
    { id: 2, name: 'Phone', price: 699 },
    { id: 3, name: 'Tablet', price: 499 },
    { id: 4, name: 'Headphones', price: 199 },
    { id: 5, name: 'Watch', price: 299 }
  ];
}

import { revalidateTag } from 'next/cache';
import { getAllProducts, Product } from '@/lib/db';

async function getCachedProducts(): Promise<Product[]> {
  'use cache';
  return getAllProducts();
}

async function invalidateProductsCache(): Promise<void> {
  'use server';
  revalidateTag('products');
}

export default function Page() {
  return (
    <div className="p-8">
      <h1 className="text-2xl font-bold mb-6">Product Listing</h1>
      <ProductList />
      <CacheInvalidationForm />
    </div>
  );
}

async function ProductList() {
  const products = await getCachedProducts();

  return (
    <ul className="space-y-2 mb-8">
      {products.map((product) => (
        <li key={product.id} className="p-4 border rounded">
          {product.name} - ${product.price}
        </li>
      ))}
    </ul>
  );
}

function CacheInvalidationForm() {
  const invalidateCache = async (): Promise<void> => {
    'use server';
    revalidateTag('products');
  };

  return (
    <form
      action={async () => {
        'use server';
        await revalidateTag('products');
      }}
      className="p-4 border rounded"
    >
      <h2 className="text-lg font-semibold mb-4">Cache Management</h2>
      <button
        type="submit"
        className="px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600"
      >
        Refresh Products Cache
      </button>
    </form>
  );
}
